package local.tvmorph.tv;
import android.content.Context;import android.net.Uri;import androidx.media3.datasource.*;import androidx.media3.common.C;import java.net.*;import java.io.*;import java.util.*;
/** LAN-only streaming: validates every HLS segment/key URL; never follows redirects or forwards credentials. */
final class LanMediaDataSource extends BaseDataSource {
 private final Context context;private final String root;private HttpURLConnection connection;private InputStream input;private Uri uri;private boolean started;private long remaining=C.LENGTH_UNSET;
 LanMediaDataSource(Context c,String address){super(true);context=c.getApplicationContext();root=address;}
 public long open(DataSpec spec)throws IOException{transferInitializing(spec);try{URI base=LanPolicy.validate(root),next=LanPolicy.validate(spec.uri.toString());Set<InetAddress> allowed=new HashSet<>(Arrays.asList(InetAddress.getAllByName(base.getHost())));for(InetAddress a:InetAddress.getAllByName(next.getHost()))if(!allowed.contains(a))throw new IOException("Media resource points outside the selected device.");if(base.getScheme().equals("https")&&!next.getScheme().equals("https"))throw new IOException("Insecure media resource rejected.");LanHttpClient.Target target=LanHttpClient.open(next.toString());if(!allowed.contains(InetAddress.getByName(target.ip)))throw new IOException("Media address changed outside selected device.");connection=target.connection;connection.setConnectTimeout(6000);connection.setReadTimeout(12000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Host",next.getRawAuthority());connection.setRequestProperty("User-Agent","MorphTV LocalNetwork/1");String auth=LanVault.auth(context,LanPolicy.origin(next));if(!auth.isEmpty())connection.setRequestProperty("Authorization",auth);connection.setRequestProperty("Accept-Encoding","identity");if(spec.position>0||spec.length!=C.LENGTH_UNSET)connection.setRequestProperty("Range","bytes="+spec.position+"-"+(spec.length==C.LENGTH_UNSET?"":spec.position+spec.length-1));int status=connection.getResponseCode();if(status<200||status>299)throw new IOException("Local stream HTTP "+status+". Redirects are not followed.");if(spec.position>0&&status!=206)throw new IOException("Device does not support seek ranges.");input=connection.getInputStream();uri=spec.uri;started=true;transferStarted(spec);remaining=spec.length==C.LENGTH_UNSET?connection.getContentLengthLong():spec.length;return remaining;}catch(Exception e){close();if(e instanceof IOException)throw (IOException)e;throw new IOException("Local stream connection failed.");}}
 public int read(byte[] bytes,int offset,int length)throws IOException{if(length==0)return 0;if(input==null)throw new IOException("Stream closed.");if(remaining==0)return C.RESULT_END_OF_INPUT;int n=input.read(bytes,offset,remaining<0?length:(int)Math.min(length,remaining));if(n<0)return C.RESULT_END_OF_INPUT;if(remaining>0)remaining-=n;bytesTransferred(n);return n;}
 public Uri getUri(){return uri;}
 public Map<String,List<String>> getResponseHeaders(){return connection==null?Collections.emptyMap():connection.getHeaderFields();}
 public void close(){try{if(input!=null)input.close();}catch(IOException ignored){}input=null;if(connection!=null)connection.disconnect();connection=null;uri=null;if(started){started=false;transferEnded();}}
}
